using System;using System.Data.SqlClient;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class ApplicationTimelinePage:UserControl{public ApplicationTimelinePage(){Dock=DockStyle.Fill;BackColor=Theme.Background;Padding=new Padding(18);var title=Ui.Label(L.Fa?"تایم‌لاین درخواست‌های استخدام":"Application timeline",18,true);title.Dock=DockStyle.Top;title.Height=52;var grid=Ui.Grid();grid.DataSource=Database.Query(@"SELECT TOP 100 a.Id,j.Title Job,c.Name Company,a.Stage,a.Score,a.AppliedAt,(SELECT TOP 1 ScheduledAt FROM Interviews i WHERE i.ApplicationId=a.Id ORDER BY ScheduledAt DESC) NextInterview FROM Applications a JOIN Jobs j ON j.Id=a.JobId LEFT JOIN Companies c ON c.Id=j.CompanyId ORDER BY a.AppliedAt DESC");Controls.Add(grid);Controls.Add(title);}}
}
